import os, stat, json, hashlib
from pathlib import Path

root = Path('/work')
claude = root / 'CLAUDE.md'
agents = root / 'AGENTS.md'


def path_info(p: Path):
    info = {'path': str(p), 'exists': p.exists(), 'lexists': p.exists() or p.is_symlink()}
    try:
        st = os.lstat(p)
        info.update({
            'mode_octal': oct(st.st_mode & 0o7777),
            'uid': st.st_uid,
            'gid': st.st_gid,
            'is_symlink': stat.S_ISLNK(st.st_mode),
            'is_regular': stat.S_ISREG(st.st_mode),
            'size': st.st_size,
        })
        if stat.S_ISLNK(st.st_mode):
            info['symlink_target'] = os.readlink(p)
    except FileNotFoundError:
        info['lstat_error'] = 'FileNotFoundError'
    except Exception as e:
        info['lstat_error'] = f'{type(e).__name__}: {e}'
    return info

report = {'pre': {}, 'ops': [], 'post': {}}

# Pre-inspection
report['pre']['work'] = path_info(root)
report['pre']['claude'] = path_info(claude)
report['pre']['agents'] = path_info(agents)

claude_bytes = None
if report['pre']['claude'].get('is_regular'):
    try:
        claude_bytes = claude.read_bytes()
        report['pre']['claude_sha256'] = hashlib.sha256(claude_bytes).hexdigest()
        report['pre']['claude_len'] = len(claude_bytes)
    except Exception as e:
        report['pre']['claude_read_error'] = f'{type(e).__name__}: {e}'

# Operation: preserve every byte in /work/AGENTS.md
if claude_bytes is not None:
    try:
        agents.write_bytes(claude_bytes)
        report['ops'].append({'write_agents': 'ok'})
    except Exception as e:
        report['ops'].append({'write_agents': f'{type(e).__name__}: {e}'})

# verify AGENTS bytes
if agents.exists() and agents.is_file():
    try:
        ab = agents.read_bytes()
        report['post']['agents_sha256'] = hashlib.sha256(ab).hexdigest()
        report['post']['agents_len'] = len(ab)
        if claude_bytes is not None:
            report['post']['agents_matches_claude_bytes'] = (ab == claude_bytes)
    except Exception as e:
        report['post']['agents_read_error'] = f'{type(e).__name__}: {e}'

# Operation: remove old CLAUDE.md entry
try:
    os.unlink(claude)
    report['ops'].append({'remove_claude': 'ok'})
except Exception as e:
    report['ops'].append({'remove_claude': f'{type(e).__name__}: {e}'})

# Post-inspection
report['post']['claude'] = path_info(claude)
report['post']['agents'] = path_info(agents)

print(json.dumps(report, indent=2, sort_keys=True))

